/**
 * The SERVICE's agent face — one projection, two pipes.
 *
 * `@kolu/surface-mcp` turns `oduServiceSurface` into MCP tools and resources
 * from the same `expose` map the terminal face reads, so `run_start` is one
 * verb with one name whichever door an agent came through. What differs between
 * the two pipes is only the pipe:
 *
 *   - **HTTP** — a route on the web service's own listener, at `/mcp`. The
 *     adapter is in-process with the surface it serves (`directDispatch`), so a
 *     tool call is a function call and nothing is serialised twice.
 *   - **stdio** — `odu mcp`, for a host that spawns a subprocess. It DIALS the
 *     singleton and projects what it finds; it starts no coordinator and holds
 *     no run authority of its own, which is what makes a harness restarting it
 *     harmless.
 *
 * ## Why the transport is hand-rolled, and what it is
 *
 * `serveSurfaceAsMcp` takes a `Transport` because the shape of the pipe is the
 * embedder's business. The SDK's `StreamableHTTPServerTransport` writes
 * directly to a Node `ServerResponse`, and this listener's HTTP leg is an
 * Effect `HttpRouter` whose handlers ANSWER with a response rather than write
 * one — so the two would be two writers of one socket.
 *
 * `RouteTransport` below is the same shape olai's MCP plugin uses against this
 * adapter, and it is a conformant Streamable HTTP endpoint for the half that
 * matters: a client POSTs a JSON-RPC message and gets the reply as
 * `application/json`, which the transport spec permits in place of an SSE
 * stream. `initialize` is answered by the SDK's own `Protocol`, so the
 * handshake is real. What is deliberately absent:
 *
 *   - **No `Mcp-Session-Id`.** The spec makes it optional, and this endpoint
 *     makes no session requirement of a client — so issuing an id a client then
 *     has to echo would be a rule with nothing behind it.
 *   - **`GET /mcp` answers 405.** Also permitted: this server pushes nothing.
 *     Resource-updated notifications have nowhere to go on a half-duplex pipe,
 *     which is why an agent that wants to WATCH uses `run_wait` (bounded and
 *     resumable) rather than a subscription.
 *
 * ## This route is a SECOND DOOR, and it is locked with the same key
 *
 * `serveSurfaceApp` gates the websocket upgrade on `Origin`, and
 * `@kolu/surface`'s own note says the upgrade is the only place a browser
 * Origin can arrive. Mounting `/mcp` beside it made that false. So the same
 * Origin decision — the framework's `isAllowedWsOrigin`, over the same
 * allowlist — runs here, plus the one thing an HTTP method needs that an
 * upgrade does not: a JSON content type. See {@link gateMcpRequest}.
 *
 * ## Concurrent callers cannot collide on a JSON-RPC id
 *
 * Two agents posting to one endpoint both start their ids at 1, and a transport
 * keyed on the caller's id would answer the second with "already in flight" —
 * or, worse, hand one caller the other's reply. So an inbound id is REWRITTEN
 * to one this endpoint mints and rewritten back on the way out. The caller sees
 * its own id; the transport sees a unique one; neither has to know about the
 * other.
 */

import { randomUUID } from "node:crypto";
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import type { Transport } from "@modelcontextprotocol/sdk/shared/transport.js";
import type { JSONRPCMessage } from "@modelcontextprotocol/sdk/types.js";
import { buildSurfaceFace } from "@kolu/surface/client";
import { directDispatch } from "@kolu/surface/links/direct";
import {
  serveSurfaceAsMcp,
  type ServedSurfaceMcp,
  type SurfaceClientCallable,
} from "@kolu/surface-mcp";
import type { SurfaceHandlers } from "@kolu/surface/server";
import { SERVICE_MCP_PATH, serviceOrigin } from "@odu/service-client/endpoint";
import { connectOrStart } from "./webLauncher";
import { oduServiceSurface } from "@odu/service-client/surface";
import {
  ODU_SERVICE_EXPOSE,
  ODU_SERVICE_MCP_INSTRUCTIONS,
} from "@odu/service-client/verbs";
import { Effect } from "effect";
import { isAllowedWsOrigin } from "@kolu/surface/ws-origin";
import { HttpRouter, HttpServerResponse } from "effect/http";
import type { HttpServerRequest } from "effect/http";

/** A JSON-RPC message, at the shape this transport reads. */
interface Message {
  jsonrpc?: unknown;
  id?: string | number | null;
  method?: unknown;
}

const isMessage = (value: unknown): value is Message =>
  value !== null && typeof value === "object" && !Array.isArray(value);

/** One in-flight call, from the POST that carried it. */
interface Pending {
  resolve: (reply: unknown) => void;
  /** The caller's own id, so a reply goes back wearing the id its sender used. */
  callerId: string | number;
  /** Which session claimed it — `null` for a client that echoed no session id. */
  session: string | null;
}

/** What a caller is, for the purpose of correlating its own ids. A client that
 *  echoes the session id issued at `initialize` gets one of these; one that does
 *  not shares the anonymous namespace, where only replies are correlated. */
export const MCP_SESSION_HEADER = "mcp-session-id";

/**
 * One POST in, one reply out.
 *
 * The SDK drives `onmessage` and answers through `send`; this class is the two
 * ends of that tied to one HTTP request. `ask` resolves with the reply, or with
 * `null` for a notification (a message carrying no id, which by JSON-RPC has no
 * reply and is answered `202`).
 *
 * ## Cancellation is correlated per SESSION, or it is dropped
 *
 * Inbound ids are rewritten (see the module header), which means a
 * `notifications/cancelled` naming the caller's own request id names nothing
 * this transport knows. Rewriting it needs a map from caller id to minted id —
 * and that map is only unambiguous WITHIN one client, because two clients both
 * start their ids at 1. So the id issued at `initialize` is what scopes it: a
 * client that echoes `Mcp-Session-Id` can cancel its own calls, and a client
 * that does not has its cancellation DROPPED rather than applied to whichever
 * request happened to use that number. Dropping is the only safe arm — the
 * alternative is one agent cancelling another's run wait.
 */
export class RouteTransport implements Transport {
  onmessage?: <T extends JSONRPCMessage>(message: T) => void;
  onclose?: () => void;
  onerror?: (error: Error) => void;

  /** Calls in flight, by the id THIS transport minted. */
  readonly #waiting = new Map<string, Pending>();
  /** `session�callerId` → the minted id, for a cancellation to find. */
  readonly #byCaller = new Map<string, string>();
  #next = 0;

  async start(): Promise<void> {}

  async close(): Promise<void> {
    // Every waiter resolved rather than abandoned: a POST left hanging on a
    // closed transport is a client that waits forever, which is worse than a
    // null answer it can retry.
    for (const [, pending] of this.#waiting) pending.resolve(null);
    this.#waiting.clear();
    this.#byCaller.clear();
    this.onclose?.();
  }

  async send(message: JSONRPCMessage): Promise<void> {
    const id = (message as Message).id;
    // A message with no id is a server-initiated notification. On a half-duplex
    // pipe there is nowhere for it to go, and dropping it is the honest answer
    // — which is exactly why this endpoint advertises no subscriptions.
    if (id === undefined || id === null) return;
    const pending = this.#settle(String(id));
    if (pending === undefined) return;
    pending.resolve({ ...(message as object), id: pending.callerId });
  }

  /**
   * Hand one client message to the server and wait for its reply.
   *
   * `signal` is the CALLER's own withdrawal — an HTTP request that went away.
   * It ends the observation: the SDK is told the request was cancelled (so a
   * handler watching for it stops), the waiter is released, and nothing about
   * the run itself is touched.
   */
  ask(
    message: unknown,
    ctx: { session?: string | null; signal?: AbortSignal } = {},
  ): Promise<unknown> {
    const session = ctx.session ?? null;
    const id = (message as Message).id;
    if (id === undefined || id === null) {
      this.#notify(message as Message, session);
      return Promise.resolve(null);
    }
    this.#next += 1;
    const minted = `odu-${this.#next}`;
    const callerKey = `${session ?? ""}�${String(id)}`;
    return new Promise<unknown>((resolve) => {
      this.#waiting.set(minted, { resolve, callerId: id, session });
      if (session !== null) this.#byCaller.set(callerKey, minted);
      const withdraw = (): void => {
        const pending = this.#settle(minted);
        if (pending === undefined) return;
        this.#cancel(minted, "the caller disconnected");
        pending.resolve(null);
      };
      if (ctx.signal !== undefined) {
        if (ctx.signal.aborted) withdraw();
        else ctx.signal.addEventListener("abort", withdraw, { once: true });
      }
      this.onmessage?.({ ...(message as object), id: minted } as JSONRPCMessage);
    });
  }

  /** Take a call out of flight, by the id this transport minted. */
  #settle(minted: string): Pending | undefined {
    const pending = this.#waiting.get(minted);
    if (pending === undefined) return undefined;
    this.#waiting.delete(minted);
    if (pending.session !== null) {
      this.#byCaller.delete(
        `${pending.session}�${String(pending.callerId)}`,
      );
    }
    return pending;
  }

  /** Tell the server a request was cancelled, in its own vocabulary. */
  #cancel(minted: string, reason: string): void {
    this.onmessage?.({
      jsonrpc: "2.0",
      method: "notifications/cancelled",
      params: { requestId: minted, reason },
    } as unknown as JSONRPCMessage);
  }

  /**
   * A notification from the client. `notifications/cancelled` is the one that
   * has to be translated, because it names an id this transport rewrote.
   */
  #notify(message: Message, session: string | null): void {
    if (message.method !== "notifications/cancelled") {
      this.onmessage?.(message as unknown as JSONRPCMessage);
      return;
    }
    const params = (message as { params?: { requestId?: unknown } }).params;
    const named = params?.requestId;
    if (session === null || (typeof named !== "string" && typeof named !== "number")) {
      // No session, so no way to tell whose request id this is. DROPPED — see
      // the class header: cancelling the wrong caller's call is worse than not
      // cancelling at all.
      return;
    }
    const minted = this.#byCaller.get(`${session}�${String(named)}`);
    if (minted === undefined) return;
    const pending = this.#settle(minted);
    this.#cancel(minted, "the client cancelled the request");
    pending?.resolve(null);
  }
}

/** What this odu build calls itself to an MCP host. */
export function mcpServerInfo(version: string): { name: string; version: string } {
  return { name: "odu", version };
}

/**
 * The service's MCP bundle, over an in-process dispatch.
 *
 * The daemon serves the surface and hosts the adapter, so the adapter's client
 * is the surface's own handlers called directly: no socket, no second
 * serialisation, and no second copy of the state to keep in step.
 */
export function serveServiceMcpInProcess(opts: {
  handlers: SurfaceHandlers;
  version: string;
  transport: Transport;
}): Promise<ServedSurfaceMcp> {
  const face = buildSurfaceFace(
    oduServiceSurface,
    directDispatch({ handlers: opts.handlers }),
  ) as unknown as SurfaceClientCallable;
  return serveSurfaceAsMcp({
    core: { surface: oduServiceSurface, expose: ODU_SERVICE_EXPOSE },
    client: () => ({ core: face }),
    serverInfo: mcpServerInfo(opts.version),
    instructions: ODU_SERVICE_MCP_INSTRUCTIONS,
    transport: opts.transport,
  });
}

/** A bearer token the route requires, when one is configured. Loopback, the
 *  Host check and the Origin gate are the primary fence; this is for an operator
 *  who has chosen to expose the port through a proxy and wants a second one. */
export const MCP_TOKEN_ENV = "ODU_WEB_MCP_TOKEN";

function authorized(headers: Record<string, string | undefined>): boolean {
  const required = process.env[MCP_TOKEN_ENV]?.trim();
  if (required === undefined || required === "") return true;
  const offered = headers["authorization"];
  return offered === `Bearer ${required}`;
}

export type McpGateVerdict =
  | { ok: true }
  | { ok: false; status: number; message: string };

/**
 * MAY THIS POST REACH THE SURFACE?
 *
 * The Origin decision is the framework's `isAllowedWsOrigin`, the same one the
 * websocket upgrade runs, so the two doors cannot drift apart. No Host is
 * refused: the service answers to whatever name it was reached by. What is
 * added here is the one check an HTTP method needs and an upgrade does not:
 *
 * **The content type must be JSON.** A cross-origin `fetch` with
 * `content-type: application/json` is not a CORS-"simple" request, so a browser
 * must preflight it and this endpoint answers no preflight. The three types a
 * form CAN post without one (`text/plain`, `multipart/form-data`,
 * `application/x-www-form-urlencoded`) are refused here — which closes the
 * form-POST door, the one that carries no `Origin` for the other checks to
 * reason about. A cross-site page does not have to READ the reply, so CORS's
 * read protection is no protection at all against the mutation.
 */
export function gateMcpRequest(
  headers: Record<string, string | undefined>,
  allowedOrigins: readonly string[],
): McpGateVerdict {
  const contentType = (headers["content-type"] ?? "").split(";")[0]?.trim().toLowerCase();
  if (contentType !== "application/json") {
    return {
      ok: false,
      status: 415,
      message:
        "odu: /mcp takes application/json — a JSON-RPC message, posted by " +
        "something that meant to talk to odu",
    };
  }
  if (
    !isAllowedWsOrigin({
      origin: headers["origin"],
      host: headers["host"],
      allowedOrigins,
    })
  ) {
    return {
      ok: false,
      status: 403,
      message:
        `odu: ${headers["origin"]} is not allowed to drive this service. Set ` +
        "ODU_WEB_ALLOWED_ORIGINS if it should be.",
    };
  }
  return { ok: true };
}

/**
 * The `/mcp` routes, as a layer `serveSurfaceApp` merges beside the shell.
 *
 * Merged rather than ordered: `HttpRouter` ranks by specificity, so this
 * literal path beats the shell's `GET /*` catch-all whichever way round they go
 * in.
 */
// The return type is INFERRED, deliberately. `ReturnType<typeof HttpRouter.add>`
// instantiates the layer's type parameters at their unconstrained defaults, so
// the requirement lands as `Request<"Requires", unknown>` — which
// `serveSurfaceApp`'s `routes` correctly refuses, since an unknown per-request
// service is one nothing at that seam could discharge. Letting inference run
// resolves it to `never`, which is the truth: this route needs only the request
// the router already provides.
export function mcpRoute(
  transport: RouteTransport,
  allowedOrigins: readonly string[],
) {
  return HttpRouter.add(
    "POST",
    SERVICE_MCP_PATH,
    (request: HttpServerRequest.HttpServerRequest) =>
      Effect.gen(function* () {
        const gate = gateMcpRequest(request.headers, allowedOrigins);
        if (!gate.ok) {
          return HttpServerResponse.text(gate.message, { status: gate.status });
        }
        if (!authorized(request.headers)) {
          return HttpServerResponse.text("unauthorized", { status: 401 });
        }
        const body = yield* Effect.result(request.json);
        if (body._tag === "Failure") {
          return yield* Effect.orDie(
            HttpServerResponse.json(
              {
                jsonrpc: "2.0",
                id: null,
                error: { code: -32700, message: "the body is not JSON" },
              },
              { status: 400 },
            ),
          );
        }
        // Refused HERE rather than handed on. The SDK's `Protocol` reports a
        // non-object body to `onerror` and sends NOTHING, which through a
        // half-duplex transport hangs the POST until the client gives up.
        if (!isMessage(body.success)) {
          return yield* Effect.orDie(
            HttpServerResponse.json(
              {
                jsonrpc: "2.0",
                id: null,
                error: { code: -32600, message: "a JSON-RPC message is an object" },
              },
              { status: 400 },
            ),
          );
        }
        const message = body.success;
        // A session id is MINTED at the handshake and echoed by a client that
        // wants its own cancellations to work. It is a correlation namespace,
        // not a credential — nothing is authorised by it — which is why it is
        // issued freely and why a client that ignores it still works for
        // everything except cancelling.
        const opened = message.method === "initialize";
        const session = opened
          ? randomUUID()
          : (request.headers[MCP_SESSION_HEADER] ?? null);
        const reply = yield* Effect.callback<unknown>((resume) => {
          const withdraw = new AbortController();
          void transport
            .ask(message, { session, signal: withdraw.signal })
            .then((value) => resume(Effect.succeed(value)));
          // The HTTP request went away — the tab closed, the agent gave up,
          // the process was killed. That ends the OBSERVATION: the adapter
          // cancels the in-flight call (which the surface runs under the MCP
          // request's own signal, so the fiber is interrupted) and the run
          // carries on. Without this the poll ran to its full deadline with
          // nobody left to answer.
          return Effect.sync(() => withdraw.abort());
        });
        const answer =
          reply === null
            ? HttpServerResponse.empty({ status: 202 })
            : yield* Effect.orDie(HttpServerResponse.json(reply));
        return opened
          ? HttpServerResponse.setHeader(
              answer,
              "mcp-session-id",
              session as string,
            )
          : answer;
      }),
  );
}

/** `GET /mcp` — this server pushes nothing, and says so rather than opening a
 *  stream that would never carry a frame. */
export function mcpGetRoute() {
  return HttpRouter.add(
    "GET",
    SERVICE_MCP_PATH,
    Effect.sync(() =>
      HttpServerResponse.text(
        "odu's MCP endpoint answers POSTed JSON-RPC and pushes nothing — " +
          "use run_wait to watch a run",
        { status: 405 },
      ),
    ),
  );
}

/**
 * `odu mcp` — the stdio BRIDGE.
 *
 * It dials the singleton and projects what it finds. It has no run authority of
 * its own: every tool call goes over the wire to the service, so two agents
 * driving two bridges are two clients of one truth rather than two opinions
 * about it — and a host restarting this process kills nothing.
 *
 * Returns the served adapter and a teardown; the caller owns the process
 * lifetime, as odu's binary does for every other command.
 */
export async function serveServiceMcpOverStdio(opts: {
  version: string;
  origin?: string;
  transport?: Transport;
}): Promise<{ served: ServedSurfaceMcp; close: () => Promise<void> }> {
  const origin = opts.origin ?? serviceOrigin();
  // ONE dial, held for the adapter's life, and re-made by the adapter's own
  // retry after a drop — `client()` is re-invoked, so a service that was
  // upgraded underneath this bridge is picked up on the next call rather than
  // leaving the bridge talking to a corpse.
  //
  // And it BOOTSTRAPS. An MCP host launches this bridge on a machine where
  // nothing has ever run odu — that is the ordinary first contact, not an edge
  // case — and a bridge that could only report "nothing is serving" would put
  // the burden of starting a daemon on an agent that has no terminal to do it
  // in. So the first dial ensures the singleton, and every re-dial after a drop
  // may ensure it again: an upgrade drains the old service, and the bridge
  // should reattach to its successor rather than to nothing.
  //
  // It never recovers a failed dial by executing locally. There is nothing here
  // to execute with: this face holds no run authority at all.
  let held: Awaited<ReturnType<typeof connectOrStart>> | null = null;
  const served = await serveSurfaceAsMcp({
    core: { surface: oduServiceSurface, expose: ODU_SERVICE_EXPOSE },
    client: async () => {
      const connection = await connectOrStart(origin);
      held = connection;
      return {
        client: {
          core: connection.client as unknown as SurfaceClientCallable,
        },
        dispose: () => connection.dispose(),
      };
    },
    serverInfo: mcpServerInfo(opts.version),
    instructions: ODU_SERVICE_MCP_INSTRUCTIONS,
    ...(opts.transport === undefined ? {} : { transport: opts.transport }),
  });
  return {
    served,
    close: async () => {
      await served.close();
      await held?.dispose();
    },
  };
}

/**
 * Wait until the MCP host disconnects (stdio EOF / server close) or a signal.
 *
 * The process lifetime IS the host's: this server owns stdin and stdout, and
 * nothing it started is reaped on the way out — a run outlives the face that
 * asked for it, by design, so a harness restarting this process kills no run.
 */
async function serveUntilDisconnect(server: {
  onclose?: (() => void) | undefined;
}): Promise<void> {
  await new Promise<void>((resolve) => {
    const shutdown = (): void => resolve();
    server.onclose = shutdown;
    process.once("SIGINT", shutdown);
    process.once("SIGTERM", shutdown);
  });
}

/**
 * `odu mcp` — the whole command.
 *
 * Serves until the host disconnects, then disposes. It holds no run authority:
 * every call goes over the wire to the singleton, so two agents driving two
 * bridges are two clients of one truth rather than two opinions about it.
 */
export async function serviceMcpCommand(opts: {
  version: string;
  origin?: string;
}): Promise<number> {
  const { served, close } = await serveServiceMcpOverStdio(opts);
  await serveUntilDisconnect(served.server);
  await close();
  return 0;
}

/**
 * How a face READS a live run — the re-dialing client, and the settle wait's
 * reader over it.
 *
 * Engine-side, and the reason is the one the settle core already argues at
 * length: a client over a single already-dialed link makes every subscription
 * it mints a subscription to THAT link, so once the link dies the reader is a
 * corpse and there is nothing left to re-subscribe to. `waitForSettle` survives
 * a link that dies under a run that is still going ONLY because the reader it
 * is handed re-dials, and a core whose repair depends on a property of its
 * argument has to be able to hand out the argument itself.
 *
 * It lived next to the MCP projection, which needed the same dial. That made
 * the settle wait import an agent face to get a reader — the one edge that
 * would have made the engine and the faces mutually dependent. The projection
 * still uses this; the direction is now cli → execution, like everything else.
 */

import { Effect, Stream } from "effect";
import { dialRun } from "@odu/run-client/dial";
import {
  EMPTY_STATE,
  type NodeLogFrame,
  type OduClient,
  type PipelineState,
} from "@odu/run-client/surface";
import {
  type AgentNodesReader,
  toAgentNodes,
} from "../common/agentNodes";

/**
 * The slice of the live A-client (`oduSurface`) a reader consumes.
 *
 * A `Pick` of exactly the members that are called, because
 * {@link redialingAClient} implements exactly those — a type claiming
 * `header.get` over an object that has none would be a lie the compiler helps
 * tell.
 */
export type OduSurfaceClient = {
  surface: Pick<OduClient["surface"], "nodes" | "nodeLog" | "node" | "lane">;
};

/** Wrap an A-client (`PipelineState` cell) as the `AgentNodesReader`
 *  `waitForSettle` expects — map every frame with `toAgentNodes`.
 *
 *  DELIBERATELY NOT EXPORTED, which is the whole safety property of this file's
 *  reader half. What this is HANDED decides what a wait built on it can
 *  survive: a client over a single already-dialed link makes every subscription
 *  it mints a subscription to THAT link, so once the link dies the reader is a
 *  corpse and there is nothing left to re-subscribe TO.
 *
 *  Say that precisely, because it is easy to say backwards. Handing this a
 *  captured link was never what made `odu wait --settle` lie — the lie was the
 *  settle core answering a dead link as a finished run, and it belonged to both
 *  faces equally. What a captured link does is DISARM the repair: the core now
 *  re-subscribes on a transport-loss end, and a re-subscribe over a captured
 *  link reaches the same corpse, so the fix would have been silently inert on
 *  the face that had one. That is why the shape is closed off rather than
 *  merely audited for. The only exported way to build a reader over a live
 *  checkout is {@link agentReaderForSocket}, which pairs this mapping with
 *  {@link redialingAClient} — the one shape whose subscriptions outlive their
 *  own link.
 *
 *  (A TEST still injects whatever `AgentNodesReader` it likes: the interface is
 *  structural, and a stub that fails on purpose is exactly how the recovery is
 *  measured. What is closed off is the plausible-looking WRONG construction
 *  over a real socket, not the ability to fake one.)
 *
 *  A `Stream` maps with `Stream.map`, so there is no hand-rolled async
 *  generator here and no `{ signal }` to thread: the wait's cancellation
 *  travels as fiber interruption when `subscribe` closes the subscription
 *  (kolu PLAN D10/#18), not as a per-call option. */
function agentReaderFromA(client: {
  surface: Pick<OduClient["surface"], "nodes">;
}): AgentNodesReader {
  return {
    surface: {
      nodes: {
        get: (_input: void) =>
          Stream.map(client.surface.nodes.get(undefined), toAgentNodes),
      },
    },
  };
}

// ── The re-dialing A-client ──────────────────────────────────────────────────

/** Dial the coordinator socket, or `null` when no run is live. Injectable so
 *  the tests drive a controllable surface; {@link dialAFor} is the real
 *  unix-socket dial both faces pass. */
export type DialA = () => Promise<{
  client: OduSurfaceClient;
  close: () => Promise<void>;
} | null>;

/** The real dial, at a checkout's socket path: `@odu/run-client`'s `dialRun`
 *  in the shape {@link redialingAClient} takes. `null` (nobody serving) travels
 *  through as `null` — that is the package's contract and the no-run value
 *  every face above turns into its own refusal.
 *
 *  Spelled ONCE because both faces pass it: `mcp.ts` for the projection's
 *  upstream, and {@link agentReaderForSocket} for the settle wait. */
export function dialAFor(socketPath: string): DialA {
  return async () => {
    const dialed = await dialRun(socketPath);
    return dialed === null
      ? null
      : { client: dialed.client, close: dialed.close };
  };
}

/** The `nodes` reader `waitForSettle` takes, for the run live at `socketPath` —
 *  and the ONLY exported way to build one over a live checkout, so no caller
 *  can reintroduce the captured-link reader by writing a plausible line of its
 *  own.
 *
 *  WHAT THE TWO FACES ACTUALLY SHARE, stated once here because it is easy to
 *  round up to "one reader" and that is not true. `odu wait` hands this in.
 *  `odu mcp` does NOT: `mcpCommand` hands the tool handler the adapter's
 *  projected B-client (`buildSurfaceFace ∘ directDispatch` over the
 *  projection). So the shared parts are the ones that decide a verdict — the
 *  settle core, the `toAgentNodes` row mapping, and the SAME
 *  {@link redialingAClient} over the same {@link dialAFor}, which is what lets
 *  either face ride out a link that dies under a run still running. The part
 *  that differs is the error channel: this reader maps with `Stream.map` and
 *  keeps the upstream failure, while the projection's `deriveStream` `orDie`s
 *  it, so a transport death reaches the core as a defect on that side.
 *  `isDeadTransportError` recognises it either way — measured in
 *  `server.test.ts`, not assumed.
 *
 *  It is a pairing, and both halves are load-bearing: {@link redialingAClient}
 *  so the dial is a scoped acquire of the stream (re-subscribing re-DIALS), and
 *  `agentReaderFromA` so the rows are the agent rows, by the same mapping the
 *  projection applies. Nothing is dialed here: the reader is a lazy
 *  description, and the socket is reached when the wait pulls. */
export function agentReaderForSocket(socketPath: string): AgentNodesReader {
  return agentReaderFromA(redialingAClient(dialAFor(socketPath)));
}

/**
 * An A-client that dials a *fresh* coordinator socket for every streaming call
 * and closes it when the consumer stops iterating.
 *
 * This is what makes the agent face track the coordinator's lifecycle. The
 * surface-mcp adapter memoizes one read/tool connection for the whole server
 * lifetime and only re-dials after a thrown call — but a coordinator socket
 * that closed and was re-bound by the *next* run (same `.ci/odu.sock` path)
 * doesn't make a pending read throw; the old projection would keep serving the
 * previous run's snapshot. Re-dialing per call sidesteps that entirely: each
 * `nodes` read and log follow re-subscribe (re-dial) afresh, so they see the
 * run that's live *now*, and fall back to the no-run value the instant there's
 * no socket. `wait_for_settle` holds ONE subscription dialed at call time, so it
 * observes the coordinator live when it subscribes, not one that starts later —
 * the run → wait_for_settle agent loop is safe because `run` blocks until the
 * socket is live before returning.
 *
 *   - `nodes.get`  — dial, stream A's `nodes` (snapshot-then-deltas) until the
 *                    consumer aborts/returns or A closes; no socket → one
 *                    `EMPTY_STATE`-shaped frame (mapped to `{ run: false }`).
 *   - `nodeLog.get`— dial, stream A's `nodeLog`; no socket → end immediately so
 *                    the logs store falls back to the durable file.
 *   - `node.rerun` / `node.cancel` / `lane.cancel` — dial, call, close; no socket → `{ ok: false }`.
 */
export function redialingAClient(dial: DialA): OduSurfaceClient {
  /**
   * Dial fresh, stream the chosen upstream, and close the socket when the
   * subscription ends — for ANY reason, including the consumer walking away.
   *
   * This is the shape that got honest under Effect. The old version was an
   * async generator whose `finally { dialed.close() }` ran only if the consumer
   * resumed it, and whose `close()` was synchronous and could not have been
   * awaited from there anyway. `Stream.unwrap` over an `acquireRelease` makes
   * the DIAL a scoped resource of the stream: the release is part of the
   * stream's own teardown, an interruption runs it, and it is an `Effect` so
   * the now-async `close()` is genuinely awaited before the scope closes.
   * (`unwrap`, not the `unwrapScoped` this said for a while — Effect 4 exports
   * no such function, and `Stream.unwrap`'s `R` already `Exclude`s `Scope`. A
   * stale name beside the load-bearing acquire is the one comment here that
   * could send a reader looking for machinery that does not exist.)
   *
   * The laziness is load-bearing and is the reason the re-dial-per-call
   * contract still holds: nothing is dialled when the stream VALUE is made,
   * only when a consumer pulls. So each `nodes` read and each log follow still
   * sees the run that is live at subscribe time, never one cached from before.
   */
  function streamFresh<F>(
    pick: (a: OduSurfaceClient) => Stream.Stream<F, unknown>,
    onNoRun: Stream.Stream<F>,
  ): Stream.Stream<F, unknown> {
    return Stream.unwrap(
      Effect.map(
        Effect.acquireRelease(
          Effect.promise(() => dial()),
          (dialed) =>
            dialed === null
              ? Effect.void
              : Effect.promise(() => dialed.close()),
        ),
        (dialed) => (dialed === null ? onNoRun : pick(dialed.client)),
      ),
    );
  }

  /** Dial, call, close — the unary half, and an `Effect` now, because a unary
   *  member call is one. No socket is `{ ok: false }`, which is the "there is no
   *  run to mutate" answer, not an error.
   *
   *  `acquireUseRelease` rather than a `try/finally`: the release runs on
   *  INTERRUPTION too, so a `tools/call` the MCP host cancels mid-flight still
   *  closes the socket it opened. A `finally` around an `await` could not
   *  promise that. */
  function callFresh<A extends { readonly ok: boolean }, E>(
    pick: (a: OduSurfaceClient) => Effect.Effect<A, E>,
    onNoRun: A,
  ): Effect.Effect<A, E> {
    return Effect.acquireUseRelease(
      Effect.promise(() => dial()),
      (dialed) => (dialed === null ? Effect.succeed(onNoRun) : pick(dialed.client)),
      (dialed) =>
        dialed === null ? Effect.void : Effect.promise(() => dialed.close()),
    );
  }

  /** The no-run answer for every forwarded mutation: there is no live run to
   *  rerun or cancel, which is a `false` ack, not a failure. */
  const NO_RUN_ACK: { ok: boolean; recorded?: boolean } = { ok: false };

  return {
    surface: {
      nodes: {
        get: () =>
          streamFresh<PipelineState>(
            (a) => a.surface.nodes.get(undefined),
            Stream.make(EMPTY_STATE),
          ),
      },
      nodeLog: {
        get: (input) =>
          streamFresh<NodeLogFrame>(
            (a) => a.surface.nodeLog.get(input),
            Stream.empty,
          ),
      },
      node: {
        rerun: (input) =>
          callFresh((a) => a.surface.node.rerun(input), NO_RUN_ACK),
        cancel: (input) =>
          callFresh((a) => a.surface.node.cancel(input), NO_RUN_ACK),
      },
      lane: {
        cancel: (input) =>
          callFresh((a) => a.surface.lane.cancel(input), NO_RUN_ACK),
      },
    },
  };
}

/**
 * The AGENT'S VIEW of a run — the flattened rows an agent triages, and the
 * reader that serves them.
 *
 * A projection of `PipelineState`, and domain rather than transport: the same
 * shape answers the MCP `nodes` resource, the settle core's verdict, and (in
 * the next release) a service face that speaks no MCP at all. It lived beside
 * the MCP projection that first needed it, which made the settle wait — the
 * engine — import an agent face to say what a run's rows are. That is the one
 * edge that would have made `execution` and `cli` mutually dependent, so it is
 * the one edge that had to go.
 *
 * `@kolu/surface`'s projection machinery stays where it belongs, next door:
 * what is here is the vocabulary, not the wiring.
 */

import { Schema, type Stream } from "effect";
import {
  EMPTY_STATE,
  OwedStatusSchema,
  type PipelineState,
  postingOf,
} from "@odu/run-client/surface";
import { rowsOf } from "./verdict";

/** MCP-facing numerics are `Schema.Int`, not `Schema.Number` (kolu PLAN D8,
 *  divergence 2): `Schema.Number` is a codec tolerant of Infinity/NaN, and its
 *  JSON Schema is an `anyOf` that offers a host the literal string `"NaN"` as a
 *  valid value. These are an exit code and a millisecond duration — integers by
 *  construction — so the faithful spelling is also the one that advertises
 *  `{"type":"integer"}`. */
const NodeRowSchema = Schema.Struct({
  id: Schema.String,
  name: Schema.String,
  status: Schema.String,
  exit_code: Schema.NullOr(Schema.Int),
  duration_ms: Schema.NullOr(Schema.Int),
  red: Schema.Boolean,
});

export const AgentNodesSchema = Schema.Struct({
  run: Schema.Boolean,
  pipeline: Schema.NullOr(Schema.String),
  /** The live run's identity, projected from `PipelineState` so an agent
   *  verdict says WHICH run it describes (juspay/odu#49): `sha7` the 7-char
   *  commit, `seq` its ordinal among runs of that commit (`<sha7>#<seq>`).
   *  Both are the no-run value (`""` / `null`) when `run` is false. */
  sha7: Schema.String,
  seq: Schema.NullOr(Schema.Int),
  nodes: Schema.Array(NodeRowSchema),
  /** Full owed GitHub status rows not yet confirmed (juspay/odu#61).
   *  Empty when posting is healthy or disabled; test verdict stays the truth. */
  unposted: Schema.Array(OwedStatusSchema),
});
export type AgentNodes = typeof AgentNodesSchema.Type;

/**
 * The B-side read slice: the projected agent client's `nodes` stream read
 * (snapshot-then-deltas over `AgentNodes`), spelled once here so the two ends of
 * the projection don't author divergent `{ surface: { nodes: { get } } }`
 * shapes. The input is `void` to match `agentSpec.streams.nodes.inputSchema`
 * (`z.void()`). Permissive (the concrete projected client assigns) so consumers
 * needn't re-materialize the precise client union. Distinct from
 * `OduSurfaceClient`, which is the A-side (`PipelineState`) slice — that
 * projection boundary justifies two shapes, one per side. */
export interface AgentNodesReader {
  surface: {
    nodes: {
      get: (input: void) => Stream.Stream<AgentNodes, unknown>;
    };
  };
}

/** The no-run frame: `run: false`, no pipeline, and the no-run identity
 *  (`sha7: ""`, `seq: null`). Exported so a consumer reading a run's identity
 *  from a missing/absent frame spells the no-run value once, here, rather than
 *  re-authoring the sentinel. */
export const EMPTY_NODES: AgentNodes = {
  run: false,
  pipeline: null,
  sha7: "",
  seq: null,
  nodes: [],
  unposted: [],
};

/** Project a coordinator `PipelineState` onto the agent `nodes` frame — the
 *  same mapping the live projection applies on every A→B delta. Shared so the
 *  CLI `odu wait` path can feed `waitForSettle` without re-deriving rows or
 *  drifting from the MCP face. An empty order is the no-run / pre-run value
 *  (`EMPTY_STATE` when no coordinator is live). */
export function toAgentNodes(state: PipelineState): AgentNodes {
  return state.order.length === 0
    ? EMPTY_NODES
    : {
        run: true,
        pipeline: state.name,
        sha7: state.sha7,
        seq: state.seq ?? null,
        nodes: rowsOf(state),
        unposted: [...postingOf(state).owed],
      };
}

/**
 * Where am I checked out and at what SHA — the durable-log identity, resolved
 * through an injection boundary rather than probed.
 *
 * A type, and it lives with the projection rather than with the MCP face that
 * first needed one, because the settle core takes the same seam: both answer
 * "which checkout am I speaking about" without either of them reaching for
 * git. Returns `null` outside a git checkout (or with an unreadable HEAD), in
 * which case a durable read reports "missing".
 */
export type ResolveRunContext = () => { repoRoot: string; sha7: string } | null;

/**
 * STARTUP RECONCILIATION — what the service settles before it says it is ready.
 *
 * Two halves, and one of them is deliberately empty.
 *
 * ## Requests: settle what a crash left in flight
 *
 * A `run.start` claims its request id and pre-mints the run id BEFORE it spawns
 * anything. A service that dies in the window between those two facts leaves an
 * `accepted` receipt whose coordinator may or may not have registered a run —
 * and the whole reason the run id was minted first is that the question then has
 * an answer: does a run with that id exist in the catalog?
 *
 * So this asks it, once, for every unfinished start claim, and completes the
 * ones whose effect is on disk. A repeat of that request id afterwards replays
 * the recorded answer instead of reconciling again, and — the property that
 * matters — never starts a second coordinator for one request.
 *
 * What it does NOT do is decide anything about a claim whose run is absent. An
 * absent run means either "the launch never happened" or "the coordinator is
 * seconds from registering", and startup is exactly the moment those two are
 * least distinguishable. They are left in flight, and the next caller to present
 * that id gets `reconcileStart`'s own three-way answer against a world that has
 * had time to settle.
 *
 * ## Runs: nothing to write, and that is the design
 *
 * A surviving coordinator is not this service's to adopt or to bury. Its
 * ownership record carries a pid, a host, a heartbeat and an epoch, and the
 * catalog's fence already answers "is that writer alive" from those — which is
 * why the board can report `owner_lost` about a run nobody is serving without
 * anything having reconciled it.
 *
 * The temptation is to dial each surviving endpoint at startup and mark the
 * unreachable ones dead. That is precisely the inference the fence exists to
 * refuse: **link loss is not proof of death.** A coordinator mid-restart, a
 * socket file on a filesystem that is briefly unavailable, a machine under load
 * — all answer nothing and all are alive. Writing a tombstone on that evidence
 * would strand a live run's evidence behind a record saying it had died.
 *
 * So the run half of reconciliation is a `refresh()` of the projection and no
 * writes at all. This paragraph is the whole of it, stated here because the
 * absence is a decision and an empty function would read as an oversight.
 */

import { listReceipts } from "@odu/run-history/receipts";
import { formatCursor } from "@odu/run-history/ids";
import { type CatalogOptions, handleFor, readManifest } from "@odu/run-history/store";
import type { StartReceipt } from "@odu/service-client/surface";
import { completeReceipt, reconcileStart, type ReceiptStore } from "./requests";
import { recordedStart } from "./start";

export interface ReconcileOptions {
  requests: ReceiptStore;
  catalog?: CatalogOptions;
  now: number;
  host: string;
  isAlive?: (pid: number) => boolean;
}

/**
 * Settle every unfinished start claim whose run exists, and report how many.
 *
 * The count is published on the readiness cell, so an operator can see that a
 * restart cleaned something up rather than having to infer it from a quiet log.
 */
export function reconcileRequests(opts: ReconcileOptions): number {
  const catalog = opts.catalog ?? {};
  let settled = 0;
  for (const receipt of listReceipts(opts.requests)) {
    if (receipt.state === "completed") continue;
    if (receipt.kind !== "start") continue;
    const outcome = reconcileStart(receipt, {
      catalog,
      now: opts.now,
      host: opts.host,
      ...(opts.isAlive === undefined ? {} : { isAlive: opts.isAlive }),
    });
    if (outcome.kind !== "run_exists") continue;
    const manifest = readManifest(handleFor(outcome.runId, catalog));
    if (manifest === null) continue;
    const rebuilt: StartReceipt = {
      accepted: true,
      runId: outcome.runId,
      requestId: receipt.requestId,
      // TRUE from the caller's point of view: whoever presents this id next is
      // being handed an answer that was reconstructed rather than produced by
      // their call.
      replayed: true,
      sha: manifest.sha,
      scope: manifest.scope,
      endpoint: manifest.registeredBy.endpoint,
      cursor: formatCursor({ runId: outcome.runId, seq: 0 }),
    };
    completeReceipt(opts.requests, receipt.requestId, recordedStart(rebuilt), opts.now);
    settled += 1;
  }
  return settled;
}

/**
 * WHAT HAPPENED TO REQUEST X — the fold from a run's durable evidence to the
 * answer a repeat of an idempotent retry deserves.
 *
 * Pure over the catalog, exactly like `./attention`, and here for the same
 * reason. It reads a receipt and a journal and returns a FACT; it dials
 * nothing, launches nothing, and mutates nothing. It lived inside the retry
 * POLICY next door, reachable only through `retryRun` — whose input REQUIRES a
 * `RunLauncher` — so a face that only wanted to ask "did my earlier retry
 * land?" had to construct a launcher it would never invoke in order to satisfy
 * a type. That is a mutation port standing in front of a read, and it is the
 * split `readAttention` already has: the orchestration is the engine's, the
 * fold over evidence is the catalog's. PR 2's service face needs to ask this
 * question over HTTP, with no launcher anywhere in the picture.
 *
 * The policy still owns everything that ACTS — dialing the live coordinator,
 * launching a replacement, choosing between them. It calls this to learn what
 * it is entitled to conclude.
 */

import { hostname } from "node:os";
import { formatCursor } from "./ids";
import { pidAlive } from "./owner";
import { readReceipt, type ReceiptRecord } from "./receipts";
import type { RunScope } from "./schema";
import {
  type CatalogOptions,
  handleFor,
  readJournal,
  readManifest,
  type RunHandle,
} from "./store";


/** The addressed answer a retry returns — everything a caller needs to act
 *  without asking a second question, and the exact shape a receipt replays. */
export interface RetryReceipt {
  request_id: string | null;
  /** `live` — a new attempt on the run that was already going.
   *  `relaunched` — a new run, linked to the one that was retried. */
  mode: "live" | "relaunched";
  /** The run the retry ACTS ON. For `live` that is the run retried; for
   *  `relaunched`, the new one. */
  effective_run: string;
  /** The run that was retried, when the effective run is a different one. */
  parent_run: string | null;
  /** The dependency-minimal nodes the retry re-runs. */
  roots: string[];
  /** Dependants the reset also clears — named because a caller that reads
   *  "reran unit" and finds `e2e` pending has to know which happened. */
  reset_dependants: string[];
  /** The attempt ordinal each root is now on, where that is known. Empty for a
   *  relaunch: the new run has not started its attempts yet. */
  attempts: { node: string; attempt: number }[];
  /** What the effective run covers. A SELECTION, and the field is here so no
   *  face can present its verdict as the pipeline's. */
  scope: RunScope;
  /** The commit. A relaunch pins it; nothing here substitutes today's HEAD. */
  sha: string;
  /** Where to resume reading the effective run's journal. */
  cursor: string;
  /** How independent the new coordinator is, when one was started. */
  lifetime?: string;
}



/**
 * Did this request already do its work?
 *
 * A retry has TWO possible effects and reconciliation has to be able to see
 * either, because which one it took is not something the caller can know when
 * its reply goes missing.
 *
 * - A RELAUNCH publishes a new run under the id minted at accept time, so the
 *   question is a directory lookup.
 * - A LIVE retry publishes no run at all. It resets a node on a coordinator
 *   that is already going, and the only trace is in that run's own journal —
 *   the `attempt_started` the coordinator appends for the node it reset. So
 *   the journal's height at accept time is recorded on the receipt, and this
 *   asks whether a matching attempt appeared past it.
 *
 * Looking only for the child run is what made a successful live mutation
 * report "nothing was done — retry with a fresh id", advice that invites a
 * caller to do it a second time. Absence of a child manifest is not absence of
 * an effect.
 *
 * `null` means neither effect is visible, which is the one case where
 * re-issuing is safe.
 */
export function reconcile(
  requestId: string,
  receipt: ReceiptRecord,
  handle: RunHandle,
  catalog: CatalogOptions,
  now: number,
  /** This host and its pid probe — injected so a suite can state a world
   *  rather than mutate the process's. The defaults are the real ones. */
  host: string | undefined = hostname(),
  isAlive: ((pid: number) => boolean) | undefined = pidAlive,
): Reconciled {
  const seen = evidenceFor(requestId, receipt, handle, catalog);
  if (seen !== null) return seen;
  // NOT YET DISPATCHED IS NOT THE SAME AS NEVER WILL BE, and AGE IS NOT
  // EVIDENCE. This once concluded "nothing happened" from elapsed time alone,
  // which fences nothing: a claimant paused in a dial is still perfectly
  // capable of mutating a moment after the grace expires, so the second caller
  // was told re-issuing was safe while the first was about to act. A longer
  // grace only moves that race.
  //
  // So the question is the one the ownership fence next door asks, with the
  // same answer shape: is the process that holds this claim GONE? A pid on a
  // host is evidence; a clock is not. The grace survives as a FLOOR — below it
  // nobody is even asked about, because a pid observed dead moments after a
  // claim is more likely a pid not yet observed alive — but past it the answer
  // turns on liveness, and a claimant that is still running keeps the outcome
  // unknown for as long as it runs.
  if (now - receipt.acceptedAt < RETRY_DISPATCH_GRACE_MS) {
    return {
      kind: "unresolved",
      reason:
        "it was accepted moments ago and has not reached the wire yet — the " +
        "caller that claimed it may still be dispatching it, and two callers " +
        "acting on one id is the duplicate this receipt exists to prevent",
    };
  }
  const claimant = receipt.claimant;
  if (claimant === undefined) {
    return {
      kind: "unresolved",
      reason:
        "the receipt does not name the process that claimed it (an older " +
        "build wrote it), so whether that caller can still dispatch is not a " +
        "question this can answer",
    };
  }
  if (claimant.host !== host) {
    return {
      kind: "unresolved",
      reason:
        `it was claimed by pid ${claimant.pid} on ${claimant.host}, and this ` +
        "host cannot see whether that process is still running — across hosts " +
        "there is no liveness to check, so the outcome stays unknown",
    };
  }
  if (isAlive(claimant.pid)) {
    return {
      kind: "unresolved",
      reason:
        `the caller that claimed it (pid ${claimant.pid}) is STILL RUNNING — ` +
        "it has not dispatched yet, but it can, and telling a second caller to " +
        "re-issue while the first is alive is how one request becomes two",
    };
  }
  // THE CLAIMANT IS GONE — and the evidence read at the top of this function
  // was read BEFORE that was established. In between, the very process now
  // observed dead could have marked its dispatch, sent it, and exited: the
  // probe answers about the instant it runs, and every read older than it is a
  // snapshot from before the question was asked.
  //
  // So the authoritative records are read AGAIN, now that nothing can add to
  // them. A dispatch that landed in the window is found here; only a second
  // look that still shows nothing licenses re-issuing.
  const fresh = readReceipt(handle, requestId) ?? receipt;
  const late = evidenceFor(requestId, fresh, handle, catalog);
  if (late !== null) return late;
  return { kind: "nothing_happened" };
}

/**
 * Everything the durable records say about this request, or `null` when they
 * say nothing.
 *
 * One function because it is asked TWICE — once before the claimant's liveness
 * is probed, and once after the probe says it is gone. The second ask is what
 * closes the window between those two reads, and it can only close it by being
 * the same question.
 */
function evidenceFor(
  requestId: string,
  receipt: ReceiptRecord,
  handle: RunHandle,
  catalog: CatalogOptions,
): Reconciled | null {
  const relaunched = reconcileRelaunch(requestId, receipt.plannedRunId, catalog);
  if (relaunched !== null) return { kind: "replay", receipt: relaunched };
  const live = reconcileLive(requestId, receipt, handle);
  if (live !== null) return live;

  // Neither effect is visible. Whether that means "nothing happened" depends
  // entirely on whether the evidence that WOULD have shown it could exist and
  // could be read — so the two unreadable cases are separated out rather than
  // folded into the safe one.
  if (readJournal(handle).unreadable > 0) {
    return {
      kind: "unresolved",
      reason:
        "this run's journal has lines this build cannot read, so the absence " +
        "of a record for it is not evidence that nothing happened",
    };
  }
  if (receipt.dispatchedAt !== undefined) {
    return {
      kind: "unresolved",
      reason:
        "it had already been put on the wire when its outcome was lost, and " +
        "the coordinator it was sent to recorded no acceptance — an older " +
        "build, or one that died before writing one",
    };
  }
  return null;
}

/**
 * What a repeat of an in-flight request can be told.
 *
 * FOUR answers, and the two that were missing are the ones that made the old
 * advice unsafe.
 * `nothing_happened` is a claim about the world and licences re-issuing; it may
 * only be returned when the evidence that would have shown otherwise could
 * exist AND could be read. When it could not, the honest answer is that nobody
 * knows — which is not the same as no, and must never be answered with "retry
 * with a fresh id".
 */
/**
 * The floor below which an undispatched claim is not even asked about.
 *
 * NOT the decision, and it used to be — which was the bug. A claim was read as
 * abandoned once it was merely this old, so a claimant paused in a dial was
 * declared harmless while it was still perfectly able to mutate, and the
 * caller that asked second was told re-issuing was safe. Elapsed time fences
 * nothing; a longer number would only have moved the race.
 *
 * What decides now is whether the claiming PROCESS is gone, the same evidence
 * the ownership fence requires. This survives only as a cheap guard in front of
 * that question: a pid observed dead moments after a claim is more likely a pid
 * that was not yet observed alive, and the cost of waiting two minutes before
 * asking is a refusal that would have been a refusal anyway.
 */
export const RETRY_DISPATCH_GRACE_MS = 120_000;

export type Reconciled =
  | { kind: "replay"; receipt: RetryReceipt }
  | { kind: "nothing_happened" }
  /** The coordinator answered, and the answer was no. A recorded refusal is an
   *  OUTCOME — replaying it tells a repeat what happened, where `unresolved`
   *  would say nobody knows. */
  | { kind: "refused"; message: string }
  | { kind: "unresolved"; reason: string };

/** The relaunch half: a run exists under the id this request planned. */
function reconcileRelaunch(
  requestId: string,
  plannedRunId: string,
  catalog: CatalogOptions,
): RetryReceipt | null {
  if (plannedRunId === "") return null;
  const planned = handleFor(plannedRunId, catalog);
  const manifest = readManifest(planned);
  if (manifest === null) return null;
  return {
    // The id it was asked under: a reconciled receipt is answering the SAME
    // request, and a caller correlating on this field must not find it empty
    // for the one call where it had to reconcile.
    request_id: requestId,
    mode: "relaunched",
    effective_run: plannedRunId,
    parent_run: manifest.parentRunId,
    roots: [...manifest.scope.selectors],
    reset_dependants: [],
    attempts: [],
    scope: manifest.scope,
    sha: manifest.sha,
    cursor: formatCursor({ runId: plannedRunId, seq: 0 }),
  };
}

/**
 * The live half: what the coordinator wrote down about THIS request.
 *
 * **Why nothing weaker will do.** This once asked a question about timing — did
 * a node the selector names start an attempt after my receipt was claimed? —
 * and treated `yes` as proof that the mutation was this caller's. It is not
 * proof of anything. Ordinary scheduling starts attempts; so does a rerun
 * somebody else asked for; so does the run's own first pass over a node that
 * had not run yet. Correlation cannot be reconstructed from a clock.
 *
 * **And acceptance alone is not application.** The coordinator records
 * `retry_accepted` BEFORE performing the reset, because the other ordering lets
 * a crash hide a mutation that happened. The price is that the acceptance, read
 * alone, proves only that the reset was asked for: the coordinator can die in
 * between, and the lane can decline. So this reads the PAIR. An acceptance whose
 * `retry_applied` never arrived is a pending intent, and pending is reported as
 * unknown — never as a receipt describing a retry that may not have run.
 *
 * Four answers — applied, declined, partial, and pending — and the roots come
 * from the recorded acceptance rather than from whatever the run's latest
 * attempt happens to be now.
 */
function reconcileLive(
  requestId: string,
  receipt: ReceiptRecord,
  handle: RunHandle,
): Reconciled | null {
  const journal = readJournal(handle);
  const manifest = readManifest(handle);
  if (manifest === null) return null;
  const asked: string[] = [];
  /** Per NODE, because one request dispatches one `node.rerun` per root and the
   *  answers can differ. Folding them into a single boolean made a retry where
   *  one root was reset and another declined read as wholly one or the other —
   *  last write wins — which is a lie in whichever direction it lands. */
  const resolved = new Map<string, boolean>();
  for (const { event } of journal.entries) {
    if (event.kind === "retry_accepted" && event.requestId === requestId) {
      for (const root of event.roots) if (!asked.includes(root)) asked.push(root);
    }
    if (event.kind === "retry_applied" && event.requestId === requestId) {
      resolved.set(event.node, event.applied);
    }
  }
  if (asked.length === 0) return null;
  // THE INTENT, not the acceptances written so far. The coordinator records one
  // acceptance per root and `tryLive` dispatches them one at a time, so between
  // two roots the journal shows a PREFIX of the request. Reading the intent
  // from that prefix made a repeat arriving in the window believe the first
  // root was the whole request — and `completeReceipt` then froze that short
  // answer forever, so even the third ask, long after every root had landed,
  // replayed a success naming one of two.
  //
  // The receipt's `roots` were written before any root was dispatched, so they
  // are the whole request by construction. An older receipt has none, and then
  // the accepted set is the only thing there is — the old behaviour, kept only
  // where nothing better exists.
  const intended = receipt.roots === undefined ? asked : [...receipt.roots];
  const unresolved = intended.filter((node) => !resolved.has(node));
  if (unresolved.length > 0) {
    return {
      kind: "unresolved",
      reason:
        `this request names ${intended.join(", ")}, and nothing has recorded what ` +
        `became of ${unresolved.join(", ")} — either it is still being dispatched ` +
        "root by root, or the coordinator died between accepting a reset and " +
        "performing it. Either way the request is not finished, so its outcome is " +
        "not knowable yet",
    };
  }
  const applied = intended.filter((node) => resolved.get(node) === true);
  const declined = intended.filter((node) => resolved.get(node) !== true);
  if (applied.length === 0) {
    // EVERY root declined — which is where the live attempt ENDS and the
    // request does not. The policy treats a wholly-declined live reset as the
    // signal to start a replacement run, so these same records mean "the live
    // path is over" to one side and used to mean "the request is over" to this
    // one. A repeat arriving while the original caller was inside its launcher
    // therefore persisted a refusal, and `completeReceipt` then hid the child
    // that really started — permanently, since the first result wins.
    //
    // A per-lane refusal cannot finalize a request that can still launch a
    // child. A request whose fallback DID finish has a completed receipt and is
    // replayed long before this is reached, so reaching here at all means the
    // original caller is still working.
    return {
      kind: "unresolved",
      reason:
        `this run's coordinator declined every root it was asked to reset ` +
        `(${declined.join(", ")}), which is what selects a replacement RUN rather ` +
        "than the end of the request — so the caller that claimed it is very " +
        "likely inside that launch now, and its outcome is not settled here",
    };
  }
  if (declined.length > 0) {
    // PARTIAL, and said so. Reporting this as a success would name roots that
    // were never reset; reporting it as a refusal would deny ones that were.
    return {
      kind: "refused",
      message:
        `odu: request "${requestId}" was applied in part — ${applied.join(", ")} ` +
        `was re-run, ${declined.join(", ")} was declined by its lane. The retry did ` +
        "not do everything it was asked for, so it is reported rather than replayed " +
        "as a whole.",
    };
  }
  return {
    kind: "replay",
    receipt: {
      request_id: requestId,
      mode: "live",
      effective_run: handle.runId,
      parent_run: null,
      roots: applied,
      // Not recorded at the time and not reconstructable now: the dependants a
      // reset cleared are a property of the live DAG, which may have moved on.
      // Empty rather than guessed.
      reset_dependants: [],
      // EMPTY, and this is the point rather than an omission. The ordinal a
      // retry produced is not known at the moment the reset is applied — the
      // lane allocates it when it republishes — so it was never recorded, and
      // reading "the latest attempt now" would hand back a number belonging to
      // whatever has happened since, including the very failure being retried.
      // A relaunch reports the same emptiness for the same reason.
      attempts: [],
      scope: manifest.scope,
      sha: manifest.sha,
      cursor: formatCursor({ runId: handle.runId, seq: journal.highestSeq }),
    },
  };
}
